insert into public.intro_articles (id, category_id, title, content, instructions, img_path, user_feedback, visible) values
  (6, null, '@MarsRebel', 'Konec mlčení! Pravda musí ven!!!!!!!!!!!!
insert into public.intro_questions (id, article_id, term, description) values
  (8, 6, 'Dezinformace', 'Úmyslně šířená nepravdivá informace.'),
  (9, 6, 'Konspirační teorie', 'Myšlenka, že důležité události nejsou náhodné, ale že za nimi stojí spiknutí mocných lidí. Její zastánci často nevěří oficiálním vysvětlením a místo toho spoléhají na domněnky.'),
  (10, 6, 'Deepfake', 'Technologie, která pomocí umělé inteligence vytváří falešná videa, obrázky nebo zvuky, například tak, že někomu změní obličej nebo hlas, aby to vypadalo skutečně.'),
  (11, 6, 'Manipulace', 'Skryté ovlivňování lidí tak, aby jednali nebo mysleli určitým způsobem, často bez toho, aby si to uvědomovali.'),
  (12, 6, 'Elity', 'Lidé s velkým vlivem a mocí ve společnosti, například politici, bohatí podnikatelé, slavní umělci nebo vědci.');
insert into public.manipulative_texts (id, category_id, intro_article_id, instructions, manipulative_parts, user_feedback, visible) values
  (32, 11, 6, 'Jak už víš, zprávu rozšířil právě Ivan – komunální politik, který si říká MarsRebel. Má malou, ale hlasitou základnu sledujících. Tvrdí, že už léta odhaluje pravdu, kterou „nám elity nechtějí říct“. Jeho příspěvky jsou plné silných emocí, dramatických tvrzení a výzev k akci. Ale co ho k tomu vede? Podívej se blíž. Najdeš v jeho textech stopy po tom, proč to vlastně dělá? Vyber dvě hlavní motivace.', '[]'::jsonb, null, false);
insert into public.manipulative_motivations (id, text_id, motivation, definition) values
  (3, 32, 'Mocenský důvod', 'Autor si chce budovat vliv, status nebo autoritu.'),
  (4, 32, 'Finanční důvod', 'Autor chce vydělat, získat podporu nebo zpeněžit obsah.'),
  (5, 32, 'Nízká mediální gramotnost', 'Autor nerozezná, co je věrohodné, a důvěřuje automaticky.'),
  (6, 32, 'Emoce', 'Komentář je reakcí na obavy nebo úzkost.'),
  (7, 32, 'Diskreditace oponenta', 'Autor se snaží zesměšnit, znevěrohodnit nebo urazit ty, kdo nesouhlasí.'),
  (9, 32, 'Polarizace společnosti', 'Komentář staví lidi proti sobě a dělí svět na „my vs. oni“.');
insert into public.manipulative_comments (id, text_id, motivation_id, comment, username, explanation) values
  (6, 32, 9, 'To jsem říkala už dávno! Elity si hrajou na bohy a lžou nám, jak jsme všichni na jedné lodi. Kecy, kecy, kecy. Lidi, proberte se už, proboha!', '@jana.probuzena', 'Polarizace společnosti: V komentáři se společnost dělí na „my“ (běžní lidé) a „oni“ (elity, které lžou a manipulují). Takové rozdělování lidí na dvě nesmiřitelné skupiny posiluje nedůvěru, konflikt a ztěžuje racionální diskuzi.'),
  (7, 32, 6, 'To snad ne! Já mám dvě malé děti a jestli je tohle pravda, tak jsme úplně v háji. Oni nás tady fakt nechají chcípnout?! Jak se vůbec můžou takhle zachovat? Co máme dělat?! 😱😱😱', '@aneta_rychlomluvna', 'Emoce: Zmínka o dětech, zoufalé otázky a expresivní závěr komentáře („nechají nás chcípnout?!“) způsobují napětí a stres. Takové emoce snižují schopnost kriticky přemýšlet a zvyšují šanci, že člověk uvěří i neověřeným informacím.'),
  (8, 32, 5, 'Vypadá to fakt reálně… a když to má už tolik sdílení, tak na tom asi něco bude, ne? Hned jsem to poslal všem známým, když to média tutlají!', '@randomuser23', 'Nízká mediální gramotnost: Autor komentáře vychází z dojmu, že něco musí být pravda, protože to vypadá reálně a má velký počet sdílení. Nechává se tedy ovlivnit vizuálním dojmem a popularitou obsahu, místo aby ověřoval zdroj nebo fakta.'),
  (9, 32, 7, 'Ať mi ještě někdo z těch vládních poskoků zkusí říct, že tohle není pravda. Teď už mlčet nebudou, ovce. 🐑', '@marcela_fakta', 'Diskreditace oponenta: Komentující nevysvětluje svůj názor, ale zesměšňuje a uráží ty, kteří by mohli nesouhlasit. Místo argumentů používá nálepky („ovce“ nebo „vládní poskoci“), které mají snížit důvěryhodnost oponentů a umlčet diskuzi.');
insert into public.cognitive_biases (id, category_id, cognitive_bias, definition, example, visible) values
  (6, 11, 'Kotvení', 'Při rozhodování spoléháme na první informaci, kterou dostaneme.', 'Lidé si pamatují stereotyp, podle kterého jsou elity spojeny se zlými úmysly, jako je například touha po bohatství. Pokud by Ivan místo elit psal o zahrádkářích, asi by mu nikdo nevěřil.', true),
  (7, 11, 'Heuristika dostupnosti', 'Věříme tomu, co si snadno vybavíme – třeba známé obrázky z filmu.', 'Lidé si spojili Ivanovu fotku s prostředím Marsu, protože to vypadalo podobně. Na obrázku jsme mohli vidět prostředí, které odpovídá obecné představě o této planetě.', true),
  (8, 11, 'Spáčův efekt', 'Časem zapomeneme, odkud informace pochází, ale zůstane nám dojem, že je pravdivá.', 'I když sledující později zjistili, že jde o dezinformaci, zůstal jim pocit: „Něco o misi na Marsu jsem někde slyšel…“', true);
insert into public.quiz_questions (id, category_id, question, answers, visible) values
  (22, 11, 'Co je to dezinformace?', '[{"answer":"Pravdivá informace podaná zábavnou formou","correct":false},{"answer":"Neověřený názor zveřejněný na internetu","correct":false},{"answer":"Úmyslně šířená nepravdivá nebo zavádějící informace","correct":true}]'::jsonb, false),
  (23, 11, 'Tvrzení „Přistání na Marsu nemá vědecký účel, jde o spiknutí elit, které se tam chystají žít“ odpovídá nejvíce:', '[{"answer":"konspirační teorii","correct":true},{"answer":"dezinformaci","correct":false},{"answer":"omylu","correct":false}]'::jsonb, false),
  (24, 11, 'Jaká může být jedna z hlavních motivací pro šíření dezinformací?', '[{"answer":"Pomoci lidem lépe se orientovat ve vědě","correct":false},{"answer":"Vyvolat strach, ovlivnit názory nebo získat pozornost či peníze","correct":true},{"answer":"Podpořit kvalitní novinářskou práci","correct":false}]'::jsonb, false),
  (25, 11, 'Když někdo používá silné výrazy jako „vláda nás zradila“ nebo „pravda, kterou vám neřeknou“, jde pravděpodobně o:', '[{"answer":"manipulaci jazykem","correct":true},{"answer":"objektivní reportáž","correct":false},{"answer":"vědeckou analýzu","correct":false}]'::jsonb, false),
  (26, 11, 'Jak můžeš spolehlivě ověřit pravost obrázku, který vidíš na sociálních sítích?', '[{"answer":"Zeptám se autora, odkud ho má","correct":false},{"answer":"Prohlédnu si komentáře, jestli už zdroj někdo nezmínil","correct":false},{"answer":"Použiju zpětné vyhledávání obrázků (např. Google Lens)","correct":true}]'::jsonb, false),
  (27, 11, 'Jaký je příklad konfirmačního zkreslení?', '[{"answer":"Podvědomě vyhledávám informace, které podporují mé přesvědčení","correct":true},{"answer":"Nechápu text, takže ho ignoruju","correct":false},{"answer":"Klikám jen na články s titulky, které mě nezajímají","correct":false}]'::jsonb, false);
